import { voxClient } from './client'

export type VoxSearchResult = {
  id: string
  type: 'objective' | 'project' | 'task' | 'note' | 'user'
  title: string
  snippet?: string
  score: number
  url: string
}

export const voxSearch = {
  async search(query: string, tenantId: string): Promise<VoxSearchResult[]> {
    return voxClient.fetch<VoxSearchResult[]>('/search', {
      method: 'POST',
      body: JSON.stringify({ query, tenantId }),
    })
  },
}
